/**
 * 운동별 초보자 종합 가이드 — 그립·세팅 / 자극 부위 / 동작 / 조심 / 초보 팁.
 *
 * 데이터 구조:
 * - setup: 잡는 법 / 발 위치 / 자세 셋업
 * - targets: 자극이 와야 할 부위 (한국어 명) + "어디가 펌핑되는지" 한 줄 느낌
 * - cues: 동작 핵심 큐 (한 줄씩, 빠르게 훑어볼 수 있게)
 * - beginnerTips: 초보가 흔히 놓치는 포인트
 */

import { motionCategoryFor, type MotionCategory } from "@/features/workout-timer/exercise-motion";

export type ExerciseGuide = {
  /** 시작 자세 / 그립 / 발 위치 — 한 단락 */
  setup: string;
  /**
   * 준비 셋업을 한 장면씩 — 발 위치 → 상체/어깨(견갑) → 그립/손 위치 순서.
   * 튜토리얼 '영상'의 앞부분(시작 자세) 장면으로 보여준다. (없으면 setup 문단을
   * 문장 단위로 쪼개 대체)
   */
  setupSteps?: string[];
  /** 자극이 와야 할 부위 — 명칭 + 펌핑 느낌 */
  targets: { name: string; feel: string }[];
  /** 동작 핵심 큐 — 한 줄씩 */
  cues: string[];
  /** 초보 팁 — 흔한 실수 / 익숙해질 때까지 신경 쓸 것 */
  beginnerTips: string[];
  /**
   * 꿀팁 — 그립·손/발 위치·각도·템포에 따라 자극 부위가 어떻게 달라지는지 등,
   * 한 단계 위의 노하우. (일반적으로 알려진 운동 원리를 우리 표현으로 정리)
   */
  proTips?: string[];
};

